"""PTY-backed interactive terminal implementation."""

from __future__ import annotations

import errno
import fcntl
import os
import pty
import select
import signal
import struct
import subprocess
import termios
import threading
import time
from typing import Optional

from base_terminal import BaseTerminal


class HeadlessTerminal(BaseTerminal):
    """A small headless terminal backed by an interactive bash process.

    Input is sent exactly as terminal bytes, so newline, escape sequences, and
    control characters (for example ``\x03``) work as they do in a real PTY.
    Output is retained in :attr:`output`; :meth:`read_output` returns output
    not previously consumed by that method, while :meth:`get_screen` returns a
    simple current-screen representation.
    """

    def __init__(
        self,
        *,
        shell: str = "/bin/bash",
        cols: int = 120,
        rows: int = 40,
        env: Optional[dict[str, str]] = None,
    ) -> None:
        if cols <= 0 or rows <= 0:
            raise ValueError("terminal dimensions must be positive")
        self.cols = cols
        self.rows = rows
        self._lock = threading.RLock()
        self._closed = False
        self._output = ""
        self._read_position = 0
        self._screen = ""
        self._reader_done = threading.Event()

        child_env = os.environ.copy()
        child_env.setdefault("TERM", "xterm-256color")
        child_env["COLUMNS"] = str(cols)
        child_env["LINES"] = str(rows)
        if env:
            child_env.update(env)

        pid, fd = pty.fork()
        if pid == 0:
            # pty.fork gives the child a controlling terminal.  Do not use
            # --noprofile/--norc: interactive bash should source startup files.
            os.execvpe(shell, [shell, "-i"], child_env)
            os._exit(127)  # pragma: no cover

        self.pid = pid
        self._fd = fd
        self._set_winsize(rows, cols)
        flags = fcntl.fcntl(fd, fcntl.F_GETFL)
        fcntl.fcntl(fd, fcntl.F_SETFL, flags | os.O_NONBLOCK)
        self._reader = threading.Thread(
            target=self._read_loop, name="headless-terminal-reader", daemon=True
        )
        self._reader.start()

    def _set_winsize(self, rows: int, cols: int) -> None:
        try:
            winsize = struct.pack("HHHH", rows, cols, 0, 0)
            fcntl.ioctl(self._fd, termios.TIOCSWINSZ, winsize)
        except OSError:
            pass

    def _append_output(self, data: bytes) -> None:
        # PTYs normally return UTF-8, but preserve undecodable bytes rather
        # than failing the reader thread.
        text = data.decode("utf-8", errors="replace")
        with self._lock:
            self._output += text
            self._screen = self._update_screen(self._screen, text)

    @staticmethod
    def _update_screen(screen: str, text: str) -> str:
        """Apply common terminal controls sufficiently for a useful screen."""
        combined = screen + text
        # Retain printable text and common cursor movement/newline behavior.
        # Raw output remains available in output, so no information is lost.
        result: list[str] = []
        line: list[str] = []
        for ch in combined:
            if ch == "\r":
                line = []
            elif ch == "\n":
                result.extend(line)
                result.append("\n")
                line = []
            elif ch == "\b":
                if line:
                    line.pop()
            elif ch == "\t":
                line.append("\t")
            elif ch >= " " or ch == "\x7f":
                line.append(ch)
        result.extend(line)
        # Keep a bounded screen buffer; output itself is unbounded by design.
        return "".join(result)[-200000:]

    def _read_loop(self) -> None:
        while not self._closed:
            try:
                readable, _, _ = select.select([self._fd], [], [], 0.1)
            except (OSError, ValueError):
                break
            if not readable:
                try:
                    pid, _ = os.waitpid(self.pid, os.WNOHANG)
                    if pid:
                        break
                except ChildProcessError:
                    break
                continue
            try:
                data = os.read(self._fd, 65536)
            except BlockingIOError:
                continue
            except OSError as exc:
                if exc.errno not in (errno.EIO, errno.EBADF):
                    pass
                break
            if not data:
                break
            self._append_output(data)
        self._reader_done.set()

    def _drain(self) -> None:
        while True:
            try:
                data = os.read(self._fd, 65536)
            except (BlockingIOError, OSError):
                return
            if not data:
                return
            self._append_output(data)

    def send_keystrokes(self, keystrokes: str, wait_sec: float = 0.0) -> None:
        if not isinstance(keystrokes, str):
            raise TypeError("keystrokes must be a str")
        if wait_sec < 0:
            raise ValueError("wait_sec must not be negative")
        if self._closed:
            raise RuntimeError("terminal is closed")
        data = keystrokes.encode("utf-8", errors="surrogatepass")
        view = memoryview(data)
        while view:
            try:
                written = os.write(self._fd, view)
                view = view[written:]
            except InterruptedError:
                continue
            except OSError as exc:
                if exc.errno == errno.EPIPE:
                    raise RuntimeError("terminal process has exited") from exc
                raise
        if wait_sec:
            time.sleep(wait_sec)
        self._drain()

    @property
    def output(self) -> str:
        with self._lock:
            return self._output

    def read_output(self) -> str:
        with self._lock:
            value = self._output[self._read_position:]
            self._read_position = len(self._output)
            return value

    def get_screen(self) -> str:
        with self._lock:
            return self._screen

    def close(self) -> None:
        if self._closed:
            return
        self._closed = True
        try:
            os.close(self._fd)
        except OSError:
            pass
        try:
            os.kill(self.pid, signal.SIGHUP)
        except OSError:
            pass
        try:
            os.waitpid(self.pid, 0)
        except (ChildProcessError, OSError):
            pass
        if self._reader.is_alive():
            self._reader.join(timeout=1.0)

    def __enter__(self) -> "HeadlessTerminal":
        return self

    def __exit__(self, exc_type, exc_value, traceback) -> None:
        self.close()

    def __del__(self) -> None:
        try:
            self.close()
        except Exception:
            pass
