import sys, time
sys.path.insert(0, '/app')
from headless_terminal import HeadlessTerminal

t = HeadlessTerminal()
time.sleep(0.15)
t.send_keystrokes("printf 'HELLO\\n'\n", 0.15)
print('HAS_HELLO=', 'HELLO' in t.output)
t.send_keystrokes("read -p 'Name: ' name; echo " + '$name' + "\n", 0.05)
t.send_keystrokes('Alice\n', 0.15)
print('HAS_ALICE=', 'Alice' in t.output)
t.send_keystrokes("sleep 5\n", 0.05)
t.send_keystrokes('\x03', 0.15)
print('HAS_INTERRUPT=', 'sleep 5' in t.output)
t.close()
